use super::plugin_scaffold_helpers::method_decl_from_schemars_with_output;
use anyhow::Result;
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, DiffMetadata, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::{CapabilityDecl, PluginSchema};
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;

/// Runtime state of the workflow automation plugin.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
#[schemars(extend("x-oscal-subid" = "sch.software.plugin.workflows.schema@v1"))]
#[schemars(extend("x-oscal-category" = "software"))]
pub struct WorkflowsState {
    /// Operational status.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "obs.software.plugin.workflows.status@v1"))]
    pub status: String,
    /// Declared workflow pipelines.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "exp.software.plugin.workflows.workflows@v1"))]
    pub workflows: serde_json::Value,
    /// Workflow scheduler configuration.
    #[serde(default)]
    #[schemars(extend("x-oscal-subid" = "sch.software.plugin.workflows.config@v1"))]
    pub config: serde_json::Value,
}

/// Input struct for StartWorkflow method.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct StartWorkflowInput {
    /// Workflow ID to start
    pub workflow_id: String,
    /// Execution parameters require 1..=32 string steps in params.steps.
    /// Each step is agent.operation or agent.operation|{JSON object arguments};
    /// binding is at most 256 bytes and argument JSON at most 16384 bytes.
    /// The serialized execution parameters must fit 131072 bytes in total.
    #[schemars(extend("x-opdbus-private" = true))]
    pub params: Option<serde_json::Value>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, schemars::JsonSchema)]
pub struct QueryWorkflowsInput {
    pub workflow_id: Option<String>,
    /// Retrieve one exact session-owned execution, including interrupted runs.
    pub execution_id: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct WorkflowSummary {
    pub id: String,
    pub name: String,
    pub steps: Vec<String>,
    pub triggers: Vec<String>,
    pub status: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct QueryWorkflowsOutput {
    pub workflows: Vec<WorkflowSummary>,
    pub count: usize,
    /// Bounded execution history of the exact verified caller session. Progress
    /// is query-only; no workflow state watch is provided by this contract.
    pub executions: Vec<WorkflowExecutionSummary>,
    /// History is bounded; a full page may omit older executions.
    pub executions_truncated: bool,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize, schemars::JsonSchema)]
#[serde(rename_all = "snake_case")]
pub enum WorkflowExecutionStatus {
    Queued,
    Running,
    PauseRequested,
    Paused,
    CancelRequested,
    Cancelled,
    Succeeded,
    Failed,
    OutcomeUnknown,
    Interrupted,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct WorkflowExecutionSummary {
    pub execution_id: String,
    pub workflow_id: String,
    pub status: WorkflowExecutionStatus,
    pub revision: u64,
    pub accepted_at: String,
    pub completed_steps: usize,
    /// The current backend request may already have caused effects.
    pub in_flight: bool,
    pub reason: Option<String>,
    /// Terminal episode is committed through the existing private SHM owner.
    /// False with no error means publication is pending or was not attempted.
    pub episode_committed: bool,
    /// Publication failed; execution status still describes backend effects.
    pub episode_error: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct WorkflowTransitionOutput {
    pub execution_id: String,
    pub workflow_id: String,
    pub status: WorkflowExecutionStatus,
    pub revision: u64,
    /// Pause/cancel takes effect after the dispatched step settles. It never
    /// undoes backend effects; a timeout leaves its outcome unknown.
    pub in_flight: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct StartWorkflowOutput {
    pub accepted: bool,
    pub execution_id: String,
    pub workflow_id: String,
    pub status: WorkflowExecutionStatus,
    pub accepted_at: String,
}

/// Input struct for PauseWorkflow method.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct PauseWorkflowInput {
    /// Workflow ID to pause
    pub workflow_id: String,
    /// Required when this session has multiple active runs of the workflow.
    pub execution_id: Option<String>,
}

/// Input struct for ResumeWorkflow method.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct ResumeWorkflowInput {
    /// Workflow ID to resume
    pub workflow_id: String,
    pub execution_id: Option<String>,
}

/// Input struct for CancelWorkflow method.
#[derive(Debug, Clone, Serialize, Deserialize, schemars::JsonSchema)]
pub struct CancelWorkflowInput {
    /// Workflow ID to cancel
    pub workflow_id: String,
    pub execution_id: Option<String>,
    /// Force cancel even if running
    #[serde(default)]
    pub force: bool,
}

impl Default for WorkflowsState {
    fn default() -> Self {
        Self {
            status: "active".to_string(),
            workflows: serde_json::json!([{"id": "deploy", "name": "Deploy Pipeline", "steps": ["build", "test", "deploy"], "triggers": ["push", "manual"], "status": "idle"}, {"id": "backup", "name": "System Backup", "steps": ["snapshot", "archive", "verify"], "triggers": ["cron"], "status": "idle"}, {"id": "embedding-sync", "name": "Embedding Pipeline Sync", "steps": ["ingest", "chunk", "embed", "store"], "triggers": ["webhook"], "status": "idle"}]),
            config: serde_json::json!({"max_concurrent": 2, "step_timeout_secs": 120, "execution_capacity": 64, "max_steps": 32, "retry_count": 0}),
        }
    }
}

pub struct WorkflowsPlugin;
impl Default for WorkflowsPlugin {
    fn default() -> Self {
        Self
    }
}

//! Global operator cron surface backed by the v0.8.4 chat-router gateway.
//!
//! The plugin owns this schema. The native gateway owns the install-wide job
//! store and applies the configured agent's risk/tool policy at execution.
//! OP-DBUS verifies the current SID1 session and exact method capability before
//! dispatch; those credentials are never forwarded to the gateway.

use anyhow::{Result, bail};
use async_trait::async_trait;
use op_state::{ApplyResult, Checkpoint, PluginCapabilities, StateDiff, StatePlugin};
use op_state_store::{CapabilityDecl, PluginSchema, SideEffect};
use schemars::JsonSchema;
use serde::{Deserialize, Serialize};
use simd_json::OwnedValue as Value;
pub const MAX_CRON_JOBS: usize = 4096;
pub const MAX_CRON_HISTORY: u32 = 100;
pub const MAX_CRON_TEXT_BYTES: usize = 256 * 1024;
pub const MAX_CRON_TOOL_NAMES: usize = 256;
fn default_true() -> bool {
    true
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum CronScope {
    GlobalDaemon,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum CronEventSequencing {
    Unsequenced,
}

#[derive(Debug, Clone, Copy, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum CronEventDelivery {
    BestEffort,
}

/// Integrity of the native wakeup stream, independent of the full snapshot
/// that follows each wakeup. v0.8.4 has no event IDs or replay cursor, so OP-DBUS
/// does not claim that every autonomous execution notification was delivered.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct CronEventStreamIntegrity {
    pub sequencing: CronEventSequencing,
    pub delivery: CronEventDelivery,
}

impl Default for CronEventStreamIntegrity {
    fn default() -> Self {
        Self {
            sequencing: CronEventSequencing::Unsequenced,
            delivery: CronEventDelivery::BestEffort,
        }
    }
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(tag = "kind", rename_all = "lowercase", deny_unknown_fields)]
pub enum CronSchedule {
    Cron {
        expr: String,
        #[serde(default)]
        tz: Option<String>,
    },
    At {
        at: String,
    },
    Every {
        every_ms: u64,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum CronJobType {
    Shell,
    Agent,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum CronSessionTarget {
    Isolated,
    Main,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "lowercase")]
pub enum CronShellOutputFormat {
    Wrapped,
    Raw,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct CronDelivery {
    pub mode: String,
    #[serde(default)]
    pub channel: Option<String>,
    #[serde(default)]
    pub to: Option<String>,
    #[serde(default)]
    pub thread_id: Option<String>,
    #[serde(default = "default_true")]
    pub best_effort: bool,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct CronJobRecord {
    pub id: String,
    pub expression: String,
    pub schedule: CronSchedule,
    pub command: String,
    #[serde(default)]
    pub prompt: Option<String>,
    #[serde(default)]
    pub name: Option<String>,
    pub job_type: CronJobType,
    pub session_target: CronSessionTarget,
    #[serde(default)]
    pub model: Option<String>,
    pub agent_alias: String,
    pub enabled: bool,
    pub delivery: CronDelivery,
    pub delete_after_run: bool,
    #[serde(default)]
    pub allowed_tools: Option<Vec<String>>,
    pub uses_memory: bool,
    pub source: String,
    pub shell_output_format: CronShellOutputFormat,
    pub created_at: String,
    pub next_run: String,
    #[serde(default)]
    pub last_run: Option<String>,
    #[serde(default)]
    pub last_status: Option<String>,
    #[serde(default)]
    pub last_output: Option<String>,
}

/// Complete authoritative cron projection. Global scheduler settings are not
/// included because they are not among the retained nine methods and the old
/// plugin values were fabricated.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
#[schemars(extend("x-oscal-subid" = "sch.service.plugin.cron.schema@v2"))]
#[schemars(extend("x-oscal-category" = "service"))]
pub struct CronStateV2 {
    #[schemars(extend("x-oscal-subid" = "obs.service.cron.scope@v2"))]
    pub scope: CronScope,
    /// Native `/api/events` is a wakeup transport only. State below always
    /// comes from a complete bounded `/api/cron` readback.
    pub event_stream: CronEventStreamIntegrity,
    #[schemars(extend("x-oscal-subid" = "mut.service.cron.manage-jobs@v1"))]
    pub jobs: Vec<CronJobRecord>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(deny_unknown_fields)]
pub struct CronRunRecord {
    pub id: i64,
    pub job_id: String,
    pub started_at: String,
    pub finished_at: String,
    pub status: String,
    #[serde(default)]
    pub output: Option<String>,
    #[serde(default)]
    pub duration_ms: Option<i64>,
}

#[derive(Debug, Clone, Default, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ListJobsInput {}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ListJobsOutput {
    pub scope: CronScope,
    pub jobs: Vec<CronJobRecord>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct JobIdInput {
    pub job_id: String,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct GetJobOutput {
    pub scope: CronScope,
    pub job: CronJobRecord,
}

fn default_history_limit() -> u32 {
    20
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct GetHistoryInput {
    pub job_id: String,
    #[serde(default = "default_history_limit")]
    #[schemars(range(min = 1, max = 100))]
    pub limit: u32,
}
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct GetHistoryOutput {
    pub scope: CronScope,
    pub job_id: String,
    pub runs: Vec<CronRunRecord>,
}

/// v0.8.4's gateway create endpoint accepts cron expressions only. The native
/// runtime also has `at`/`every` variants, but they are not admitted here.
#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(tag = "job_type", rename_all = "lowercase", deny_unknown_fields)]
pub enum CreateJobInput {
    Agent {
        agent: String,
        #[serde(default)]
        name: Option<String>,
        schedule: String,
        #[serde(default)]
        tz: Option<String>,
        prompt: String,
        #[serde(default)]
        delivery: Option<CronDelivery>,
        #[serde(default)]
        session_target: Option<CronSessionTarget>,
        #[serde(default)]
        model: Option<String>,
        #[serde(default)]
        allowed_tools: Option<Vec<String>>,
        #[serde(default)]
        delete_after_run: Option<bool>,
        #[serde(default)]
        uses_memory: Option<bool>,
    },
    Shell {
        agent: String,
        #[serde(default)]
        name: Option<String>,
        schedule: String,
        #[serde(default)]
        tz: Option<String>,
        command: String,
        #[serde(default)]
        delivery: Option<CronDelivery>,
        #[serde(default)]
        shell_output_format: Option<CronShellOutputFormat>,
    },
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct UpdateJobInput {
    pub job_id: String,
    /// Required only when changing a shell command; the provider ignores it
    /// for other patches.
    #[serde(default)]
    pub agent: Option<String>,
    #[serde(default)]
    pub name: Option<String>,
    #[serde(default)]
    pub schedule: Option<String>,
    #[serde(default)]
    pub tz: Option<String>,
    #[serde(default)]
    pub clear_tz: Option<bool>,
    #[serde(default)]
    pub command: Option<String>,
    #[serde(default)]
    pub prompt: Option<String>,
    #[serde(default)]
    pub enabled: Option<bool>,
    #[serde(default)]
    pub uses_memory: Option<bool>,
    #[serde(default)]
    pub shell_output_format: Option<CronShellOutputFormat>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct JobMutationOutput {
    pub scope: CronScope,
    pub disposition: MutationDisposition,
    /// Provider-returned post-mutation job. v0.8.4 obtains this from its store
    /// after create/update, so this is actual readback rather than an echo.
    #[serde(default)]
    pub job: Option<CronJobRecord>,
    #[serde(default)]
    pub diagnostic: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum MutationDisposition {
    Confirmed,
    ProviderCompletedUnverified,
    Indeterminate,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct DeleteJobOutput {
    pub scope: CronScope,
    pub job_id: String,
    /// True only after the provider returned `status=ok`.
    pub provider_completed: bool,
    pub disposition: MutationDisposition,
    /// `Some(true)` means a follow-up global list confirmed absence. `None`
    /// means readback failed after provider completion; the delete is not
    /// relabelled as failed or rolled back.
    #[serde(default)]
    pub absent_on_readback: Option<bool>,
    #[serde(default)]
    pub readback_error: Option<String>,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum RunDisposition {
    Completed,
    Indeterminate,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct ManualRunResult {
    pub status: String,
    pub job_id: String,
    pub success: bool,
    pub output: String,
    pub duration_ms: i64,
    pub started_at: String,
    pub finished_at: String,
}

#[derive(Debug, Clone, Serialize, Deserialize, JsonSchema)]
#[serde(deny_unknown_fields)]
pub struct RunJobOutput {
    pub scope: CronScope,
    pub job_id: String,
    pub disposition: RunDisposition,
    #[serde(default)]
    pub result: Option<ManualRunResult>,
    /// Sanitized uncertainty detail, including a bounded native transport
    /// timeout or failure to publish observed state after a completed run.
    #[serde(default)]
    pub diagnostic: Option<String>,
}

pub struct CronPlugin;
impl Default for CronPlugin {
    fn default() -> Self {
        Self
    }
}
impl CronPlugin {
    pub fn new() -> Self {
        Self
    }
}

