30:const PLUGIN_VERSION: &str = "1.0.1";
31:pub const AUTHORIZE_CAPABILITY: &str = "elevation.authorize";
32:pub const READ_CAPABILITY: &str = "elevation.read";
33:/// Seconds an unused ticket stays valid.
